BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '1min';

DO $preflight$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE (tool_name, version) IN (('check_references', 'v2'))) <> 1 THEN
        RAISE EXCEPTION 'Expected the previous tool versions (''check_references'', ''v2'')';
    END IF;
