    tool_specific_limits, version, is_active
)
SELECT tool_name, tool_family, tool_type, next.purpose, next.input_schema::jsonb, output_schema,
       execution_type, handler_name, default_output_rows, max_output_rows,
       max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
       timeout_seconds, max_output_bytes, max_llm_result_rows,
       max_llm_result_bytes, max_llm_result_tokens,
       requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
       tool_specific_limits || '{"check_references":"at most 40 references, a draft and a methodology of at most 30000 characters each per call; this run''s references only; a draft check counts no refusal","design":"EXEC.md EXEC-PROSE","registry_state":"registered from code (market-ai-orc) under the dev flags, inactive here"}'::jsonb, next.version, false
FROM public."Tool_Catalog" AS previous
JOIN (VALUES
    ('check_references', 'v2', 'v3', '{"additionalProperties":false,"properties":{"draft":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"The whole answer text you are about to send, references unchanged, or null."},"methodology":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"The methodology text you are about to send, or null."},"references":{"description":"Value references, for example ''finding.a.estimates.primary.estimate|pp:2''.","items":{"type":"string"},"type":"array"}},"required":["references","draft","methodology"],"type":"object"}',
     'Shows what value references render to before you write the answer: give the addresses (with or without {{ }} and a format) and get each one''s displayed value, or why it does not resolve and the addresses that exist. Reads only this run''s results; no data is fetched or computed. With draft (the whole answer text you are about to send, every sentence, its references unchanged, never shortened with ...) and methodology (the methodology text you are about to send) it also lists what the answer checks would refuse: figures typed without a reference, with the addresses that equal them, and numbers without a source. Pass them in the check you already make before answering; it does not count as a refusal.')
) AS next(name, from_version, version, input_schema, purpose)
